<body>
  <div id="app"></div>

  <script>
    const state = {
      touched: {
        fullName: false,
        email: false,
        phone: false,
      },
      values: {
        fullName: "",
        email: "",
        phone: "",
      },
    };

    const root = document.getElementById("app");

    function fieldError(name) {
      if (!state.touched[name]) return "";
      const value = state.values[name].trim();
      if (name === "fullName" && !value) return "Please enter your full name.";
      if (name === "email" && !value) return "Please enter your email address.";
      return "";
    }

    function FormField({ id, label, type, name, placeholder, required = false, helperText = "" }) {
      const error = fieldError(name);
      return `
        <div class="form-field">
          <label for="${id}">${label}${required ? " *" : ""}</label>
          <input
            id="${id}"
            name="${name}"
            type="${type}"
            placeholder="${placeholder}"
            ${required ? "required" : ""}
            aria-describedby="${helperText ? `${id}-help` : ""} ${error ? `${id}-error` : ""}".trim()
            value="${state.values[name]}"
          />
          ${helperText ? `<p class="helper-text" id="${id}-help">${helperText}</p>` : ""}
          <p class="error-text" id="${id}-error" ${error ? "" : "hidden"}>${error}</p>
        </div>
      `;
    }

    function SupportContactForm() {
      return `
        <main class="support-shell">
          <section class="support-card" aria-labelledby="support-title">
            <header class="support-header">
              <span class="eyebrow">Support</span>
              <h1 id="support-title">Contact our team</h1>
              <p class="support-copy">
                Send a message to the support team and we’ll get back to you as soon as possible.
              </p>
            </header>

            <form class="support-form" novalidate>
              <div class="form-grid">
                ${FormField({
                  id: "full-name",
                  label: "Full name",
                  type: "text",
                  name: "fullName",
                  placeholder: "Jane Doe",
                  required: true,
                })}

                ${FormField({
                  id: "email-address",
                  label: "Email address",
                  type: "email",
                  name: "email",
                  placeholder: "jane@example.com",
                  required: true,
                })}

                ${FormField({
                  id: "phone-number",
                  label: "Phone number",
                  type: "tel",
                  name: "phone",
                  placeholder: "(555) 123-4567",
                  helperText: "Enter your phone number in the format (555) 123-4567 or include your country code.",
                })}
              </div>

              <div class="submit-row">
                <button type="submit">Send request</button>
              </div>
            </form>
          </section>
        </main>
      `;
    }

    function render() {
      root.innerHTML = SupportContactForm();

      const form = root.querySelector("form");
      const inputs = form.querySelectorAll("input");

      inputs.forEach((input) => {
        input.addEventListener("input", (event) => {
          state.values[event.target.name] = event.target.value;
          render();
        });

        input.addEventListener("blur", (event) => {
          state.touched[event.target.name] = true;
          render();
          const refreshed = root.querySelector(`[name="${event.target.name}"]`);
          if (refreshed) refreshed.focus();
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        state.touched.fullName = true;
        state.touched.email = true;
        state.touched.phone = true;
        render();
      });
    }

    render();
  </script>
</body>
</html>
